for(const [id,reading] of Object.entries(readingNotes)) Object.assign(notes[Number(id)-1],reading);
export const packs={};
export const topicQuestions={};
export const lessons=notes.map((n,index)=>{
 const id=index+1,pid='ml-'+(n.pid||n.pids[0]),problemIds=(n.pids||[n.pid]).map(p=>'ml-'+p),pack='ml-'+id;
 const refs=sources.filter(s=>s.lessonIds.includes(id)).map(s=>s.prefix);
 const steps=['Quan sát dữ liệu nhỏ và đoán trước kết quả.','Xác định đầu vào, thuật toán và quy tắc xử lý biên.','Chạy từng bước trên mô phỏng, thử đổi một tham số.','Viết solve(data), chạy mẫu rồi thử dữ liệu khác.','Đọc kết quả checker, giải thích chỗ sai và kiểm tra lại.'];
 packs[pack]={name:n.title,analogy:n.analogy,concept:n.concept,steps,example:n.example,trap:n.trap,complexity:problems[pid].constraints,sources:refs,label:refs.length?'Từ tài liệu và bổ sung':'Bổ sung',formula:n.formula};
 const sample=generateInput(pid,0),answer=JSON.stringify(oracle(pid,sample));
 topicQuestions[pack]=[...n.quiz,['Đầu ra phải tuân theo điều gì?','Hợp đồng và trường hợp biên của đề','Một ví dụ mẫu duy nhất','Đáp án do AI đoán'],['Kết quả chuẩn cho '+problems[pid].title+' với '+JSON.stringify(sample)+' là gì?',answer,'null','"chưa tính"'],['Kiểm tra code với dữ liệu mới giúp gì?','Phát hiện lời giải thuộc lòng hoặc bỏ trường hợp biên','Tăng score tự động','Thay thế mọi đánh giá']];
 const blocks=[
  {title:'Hình dung trước',text:n.analogy,label:refs.length?'Từ tài liệu':'Bổ sung',visualization:n.visual},
  {title:'Điểm cần hiểu',text:n.concept,label:'Từ tài liệu và bổ sung'},
  {title:'Chạm để khám phá',text:'Thay dữ liệu hoặc tham số, dự đoán thay đổi rồi chạy từng bước. '+n.example,label:'Bổ sung',interactive:true},
  {title:'Đọc sâu: công thức và điều kiện',text:n.formula+'\n'+problems[pid].constraints,label:'Bổ sung đã kiểm chứng',collapsible:true},
  {title:'Một lỗi đáng nhớ',text:n.trap,label:corrections.some(c=>refs.includes(c.source))?'Hiệu đính':'Bổ sung',collapsible:true},
  {title:'Từ ý tưởng tới Python',text:problems[pid].statement,label:'Bổ sung đã kiểm chứng',problemId:pid,code:{python:solutions[pid]},collapsible:true},
 ];
 if(demonstrations[id]) blocks.push({title:'Thử API của thư viện',text:'Một thí nghiệm nhỏ chạy độc lập giúp bạn hiểu cách dùng thư viện. Đọc kết quả và so sánh với mô phỏng; bài nộp có hợp đồng riêng ở Phòng thực hành.',label:'Bổ sung đã kiểm chứng',code:{python:demonstrations[id]},collapsible:true});
 return {id,courseId:'ml',title:n.title,kind:n.exam?'exam':id>40?'advanced':'lesson',pack,unitId:units.find(u=>id>=u.range[0]&&id<=u.range[1]).id,duration:'45–60 phút',objectives:[n.quiz[0][0].replace('?',': '+n.quiz[0][1]),'Tự thao tác trên '+n.visual+' và giải thích một thay đổi.','Viết Python cho '+problems[pid].title+' theo test đã xác minh.'],prerequisites:id===1?[]:id>40?[]:[id-1],sourcePrefixes:refs,blocks,steps,problemIds,visualization:n.visual,formula:n.formula,activityCount:8,extension:{title:'Thử một thay đổi có ý nghĩa',text:'Thay miền dữ liệu/nhật ký từng bước, nêu một giới hạn của cách hiện tại và thử ít nhất một phản ví dụ.'}};
});

export function lessonMaterial(value) {
 const lesson=typeof value==='object'?value:lessons.find(l=>l.id===Number(value));if(!lesson)return null;
 const previous=lessons[Math.max(0,lesson.id-2)],q=topicQuestions[previous.pack][0];
 return {...lesson,recall:{prompt:q[0],answer:q[1],options:q.slice(1)},itinerary:[{title:'Nhớ lại',minutes:5},{title:'Nhìn và khám phá',minutes:8},{title:'Mô phỏng từng bước',minutes:10},{title:'Tám hoạt động ngắn',minutes:8},{title:'Code và test',minutes:15},{title:'Kiểm tra và ôn lỗi',minutes:9}],interview:[],corrections:corrections.filter(c=>lesson.sourcePrefixes.includes(c.source)),activities:createLab(lesson,'lesson-'+lesson.id).questions};
}

export function createLab(lesson,seed) {
 const rng=random(String(seed)+':ml-lab'),pid=lesson.problemIds[0],n=notes[lesson.id-1],input=generateInput(pid,String(seed)+':hands-on');
 const vocabulary=[{id:'v0',left:'Input',right:'Dữ liệu được solve(data) nhận vào'},{id:'v1',left:'Contract',right:'Quy tắc đầu ra và trường hợp biên'},{id:'v2',left:'Checker',right:'Kiểm chứng kết quả theo đặc tả'}];
 const process=[{id:'s0',text:'Đọc dữ liệu và đặc tả'},{id:'s1',text:'Thực hiện thuật toán trên dữ liệu'},{id:'s2',text:'Trả kết quả đúng hợp đồng'}];
 const choice=(q,i)=>({id:'choice-'+i,kind:'choice',title:i===3?'Tìm lỗi trong cách làm':'Một câu hỏi nhỏ',prompt:q[0],options:shuffle(q.slice(1).map((text,j)=>({id:'o'+j,text})),rng),answer:'o0',explanation:q[1]+'. '+(i===3?n.trap:n.concept)});
 const questions=[...n.quiz.map(choice),{id:'order',kind:'order',title:'Xếp chuỗi xử lý',prompt:'Đặt các bước về đúng thứ tự trước–sau.',items:shuffle(process,rng),answer:process.map(s=>s.id),explanation:'Đọc đầu vào → tính toán → return kết quả.'},{id:'match',kind:'match',title:'Ghép thuật ngữ',prompt:'Ghép tên với vai trò.',pairs:vocabulary.map(({id,left})=>({id,left})),options:shuffle(vocabulary.map(({id,right})=>({id,text:right})),rng),answer:Object.fromEntries(vocabulary.map(v=>[v.id,v.id])),explanation:vocabulary.map(v=>v.left+': '+v.right).join(' · ')},{id:'output',kind:'output',title:'Bạn dự đoán máy sẽ trả gì?',prompt:'Chạy tay ví dụ nhỏ và nhập JSON. Sai số/đầu ra tương đương xử lý theo hợp đồng.',input,problemId:pid,answer:oracle(pid,input),explanation:'Kết quả chuẩn: '+JSON.stringify(oracle(pid,input))},choice(['Cách làm nào dễ chấm sai kết quả nhất?','Bỏ quy tắc biên/hòa được đề ghi rõ','Đọc đặc tả trước khi code','Dùng test kiểm tra'],3),choice(['Khi cần biết vì sao kết quả thay đổi, bạn làm gì?','Đổi một tham số và theo dõi từng bước','Đổi mọi thứ cùng lúc','Chỉ hỏi AI xem đúng không'],4)];
 return {version:1,responses:{},completed:[],drafts:{},cursor:0,questions:questions.slice(0,8)};
}
export function publicLab(lab) {return {...lab,questions:lab.questions.map(({answer,explanation,...q})=>q)};}
export function checkLab(q,value) {
 if(q.kind==='output'){try{return importOutput(q,value);}catch{return false;}}
 if(q.kind==='match')return value&&typeof value==='object'&&!Array.isArray(value)&&Object.keys(value).length===Object.keys(q.answer).length&&Object.keys(q.answer).every(k=>value[k]===q.answer[k]);
 if(q.kind==='order')return Array.isArray(value)&&JSON.stringify(value)===JSON.stringify(q.answer);
 return value===q.answer;
}
// Kept synchronous: root backend calls this checker inside its submission transaction.
import { checkOutput } from './problems.mjs';
function importOutput(q,value){const output=typeof value==='string'?JSON.parse(value):value;return checkOutput(q.problemId,q.input,output);}

export function traceFor(pid,input) {
 const expected=oracle(pid,input);
 return {kind:'ml',title:problems[pid].title,input,frames:[{caption:'Đọc đầu vào theo schema.',data:input},{caption:'Thực hiện '+problems[pid].title+'.',data:input},{caption:'Trả kết quả theo hợp đồng.',data:expected}],result:expected};
}
